from itertools import chain

from mudlab.generic.controllers.dialog_controller import DialogController
from mudlab.refinement.parspace import ParameterSpaceGenerator
from mudlab.phases.models.atom_relations import AtomRatio

class RefinerController(DialogController):
    """
        A controller for a Refiner object that keeps track
        of the solutions and residuals generated by the refinement
        algorithm.
    """

    auto_adapt_excluded = [
        "refine_method_index",
        "refinables",
        "make_psp_plots",
    ]

    register_lazy = False
    _plot_png = None

    def __init__(self, refiner, *args, **kwargs):
        super(RefinerController, self).__init__(*args, **kwargs)
        self.refiner = refiner

    # ------------------------------------------------------------
    #      GTK Signal handlers
    # ------------------------------------------------------------
    def on_cancel(self):
        self.view.hide()
        self.parent.parent.view.parent.show()

    def on_btn_initial_clicked(self, event):
        self.refiner.apply_initial_solution()
        del self.refiner
        self.on_cancel()
        return True

    def on_btn_best_clicked(self, event):
        self.refiner.apply_best_solution()
        del self.refiner
        self.on_cancel()
        return True

    def on_btn_last_clicked(self, event):
        self.refiner.apply_last_solution()
        del self.refiner
        self.on_cancel()
        return True

    def on_btn_show_plot_clicked(self, event):
        if self._plot_png is not None:
            win = self.view.show_plot_popup(self._plot_png)
            self.view["btn_show_plot"].set_sensitive(False)
            win.connect("destroy", lambda *_: self.view["btn_show_plot"].set_sensitive(True))
        return True

    # ------------------------------------------------------------
    #      Methods & Functions
    # ------------------------------------------------------------
    def _get_avg_gof(self):
        """
        Compute average GoF across all specimens using the current calculated
        pattern (call after apply_best/last/initial_solution).
        num_params = number of refined parameters for degrees-of-freedom correction.
        """
        num_params = len(self.refiner.refinables)
        values = [
            s.statistics.compute_gof(num_params)
            for s in self.model.mixture.specimens
            if s is not None
        ]
        return sum(values) / len(values) if values else 0.0

    def update_labels(self, elapsed=None):
        self.view.update_labels(
            self.refiner.history.initial_residual,
            self.refiner.history.best_residual,
            self.refiner.history.last_residual,
            gof=self._get_avg_gof(),
            elapsed=elapsed,
        )

    def generate_images(self, density=200):
        import io
        samples = self.refiner.get_plot_samples()
        labels = self.refiner.get_plot_labels()
        truths = self.refiner.history.best_solution

        psg = ParameterSpaceGenerator()
        psg.initialize(self.refiner.ranges, 199)
        for sample in samples:
            psg.record(sample[:-1], sample[-1])
        psg.plot_images(self.view.figure, truths, labels[:-1])

        buf = io.BytesIO()
        self.view.figure.savefig(buf, format='png', dpi=100, bbox_inches='tight')
        self._plot_png = buf.getvalue()
        self.view["btn_show_plot"].set_sensitive(True)

    def populate_log(self, elapsed=None):
        refiner = self.refiner
        sep = "=" * 58
        lines = [sep, "  Refinement Summary", sep, ""]

        lines.append("  Method:       %s" % refiner.method)
        lines.append("  Parameters:   %d" % len(refiner.refinables))
        if elapsed is not None:
            mins, secs = divmod(int(elapsed), 60)
            lines.append("  Time elapsed: %d:%02d" % (mins, secs))
        lines.append("")

        # Parameter table
        lines.append("  Parameters:")
        lines.append("  %-30s %12s %12s" % ("Name", "Initial", "Best"))
        lines.append("  " + "-" * 56)
        initial = refiner.history.initial_solution
        best = refiner.history.best_solution
        for i, ref_prop in enumerate(refiner.refinables):
            lines.append("  %-30s %12.6f %12.6f" % (
                ref_prop.text_descriptor, initial[i], best[i]
            ))
        lines.append("")

        # Residuals
        lines.append("  Residuals:")
        lines.append("    Initial : %.6f" % refiner.history.initial_residual)
        lines.append("    Best    : %.6f" % refiner.history.best_residual)
        lines.append("    Last    : %.6f" % refiner.history.last_residual)
        lines.append("    GoF     : %.4f  (best solution, P=%d)" % (
            self._get_avg_gof(), len(refiner.refinables)))
        lines.append("")

        # Iteration log
        iter_data = refiner.history.get_residual_per_iteration()
        if iter_data:
            lines.append("  Iteration log:")
            lines.append("  %8s  %14s" % ("Iter", "Residual"))
            lines.append("  " + "-" * 24)
            for entry in iter_data:
                iteration, residual = int(entry[0]), float(entry[1])
                lines.append("  %8d  %14.6f" % (iteration, residual))
            lines.append("")

        lines.append(sep)

        # Post-refinement validation — read-only, values are NOT changed
        validation_lines = self._build_validation_report()
        if validation_lines:
            lines.append("")
            lines.extend(validation_lines)

        self.view.set_log_text("\n".join(lines))

    _CHARGE_BALANCE_THRESHOLD = 0.05   # net charge per unit cell
    _LOEWENSTEIN_THRESHOLD    = 0.5    # max Al/(Al+Si) in tetrahedral sheet

    def _build_validation_report(self):
        """
        Run post-refinement physical checks on the current model state
        (best solution already applied).  Returns a list of log lines.
        Values are read-only — nothing is changed here.
        """
        sep = "=" * 58
        lines = [sep, "  Post-refinement Validation  (read-only)", sep, ""]
        warnings = []
        ok_checks = []

        try:
            mixture = self.model.mixture
        except AttributeError:
            lines.append("  (mixture not accessible — validation skipped)")
            lines.append(sep)
            return lines

        # Iterate over every component in every phase in the mixture
        for phase in mixture.phases:
            if phase is None:
                continue
            for comp in phase.components:
                label = "%s / %s" % (phase.name, comp.name)

                # 1. AtomRatio value range and Loewenstein check
                for rel in comp.atom_relations:
                    if not isinstance(rel, AtomRatio):
                        continue
                    v = rel.value
                    rl = "  [%s]  Relation '%s'" % (label, rel.name)

                    if not (0.0 <= v <= 1.0):
                        warnings.append(
                            "%s: value=%.4f is outside [0, 1] — "
                            "negative pn produced." % (rl, v)
                        )
                    else:
                        ok_checks.append(
                            "%s: value=%.4f  [ok]  in [0, 1]" % (rl, v)
                        )

                    # Loewenstein: Al replacing Si, value > 0.5
                    a1, a2 = rel.atom1, rel.atom2
                    if (a1 and a2 and len(a1) >= 2 and len(a2) >= 2 and
                            a1[1] == 'pn' and a2[1] == 'pn' and
                            hasattr(a1[0], 'atom_type') and
                            hasattr(a2[0], 'atom_type') and
                            a1[0].atom_type is not None and
                            a2[0].atom_type is not None and
                            a1[0].atom_type.name.startswith('Al') and
                            a2[0].atom_type.name.startswith('Si')):
                        if v > self._LOEWENSTEIN_THRESHOLD:
                            warnings.append(
                                "%s: '%s' value=%.4f exceeds 0.5 — "
                                "Loewenstein's rule violated (Al/Si > 1)."
                                % (rl, rel.name, v)
                            )
                        else:
                            ok_checks.append(
                                "%s: Loewenstein satisfied (%.4f <= 0.5)  [ok]"
                                % (rl, v)
                            )

                # 2. Negative pn check
                for atom in chain(comp.layer_atoms, comp.interlayer_atoms):
                    if atom.pn < 0.0:
                        warnings.append(
                            "  [%s]  Atom '%s': pn=%.5f is negative."
                            % (label, atom.name, atom.pn)
                        )

                # 3. Charge balance
                try:
                    layer_q, inter_q, net = comp.compute_charge_balance()
                    cb_line = (
                        "  [%s]  Charge balance: "
                        "Layer=%.3f  Interlayer=%.3f  Net=%.3f"
                        % (label, layer_q, inter_q, net)
                    )
                    if abs(net) > self._CHARGE_BALANCE_THRESHOLD:
                        warnings.append(cb_line + "  [!] imbalanced")
                    else:
                        ok_checks.append(cb_line + "  [ok]")
                except Exception:
                    pass

        if warnings:
            lines.append("  WARNINGS:")
            for w in warnings:
                lines.append("  [!] " + w.strip())
            lines.append("")

        if ok_checks:
            lines.append("  Passed checks:")
            for c in ok_checks:
                lines.append("     " + c.strip())
            lines.append("")

        if not warnings and not ok_checks:
            lines.append("  No atom relations found — nothing to validate.")
            lines.append("")

        if not warnings:
            lines.append("  All checks passed.")
        else:
            lines.append(
                "  %d warning(s) above — values were NOT changed by this check."
                % len(warnings)
            )
        lines.append(sep)
        return lines

    pass # end of class
